query getCountries(
  $lang: String
  $limit: Int
  $skip: Int
  $search: String
  $where: CountryFilter
) {
  countryCollection(
    locale: $lang
    limit: $limit
    skip: $skip
    search: $search
    where: $where
  ) {
    items {
      id
      title
      countryCode
      supported
      citiesCollection {
        items {
          id
          title
          cityCode
          supported
        }
      }
    }
  }
}

